-- Revised curriculum v2. Run inside db/setup.sql's transaction.
-- Keeps users and unlocked weeks. Backs up edits, quizzes and progress first.
CREATE TABLE IF NOT EXISTS curriculum_revisions (revision text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS curriculum_content_archive (revision text NOT NULL, kind text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(revision,kind));
CREATE TABLE IF NOT EXISTS curriculum_progress_archive (
 revision text NOT NULL, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 item_id text NOT NULL, completed boolean NOT NULL, updated_at timestamptz NOT NULL,
 PRIMARY KEY(revision,user_id,item_id)
);
INSERT INTO curriculum_content_archive SELECT 'revised-v2','lessons',COALESCE(jsonb_agg(to_jsonb(e)),'[]') FROM lesson_edits e HAVING NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_content_archive SELECT 'revised-v2','quizzes',COALESCE(jsonb_agg(to_jsonb(q)),'[]') FROM week_quizzes q HAVING NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_content_archive SELECT 'revised-v2','items',COALESCE(jsonb_agg(to_jsonb(i)),'[]') FROM learning_items i HAVING NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_progress_archive SELECT 'revised-v2',user_id,item_id,completed,updated_at FROM learning_progress WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
DELETE FROM learning_progress WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
DELETE FROM learning_items WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
INSERT INTO learning_items(id,week,kind,label)
