eck"},{"id":"w2:assignment:Apply","week":2,"kind":"assignment","label":"Apply"},{"id":"w2:assignment:Explore","week":2,"kind":"assignment","label":"Explore"},{"id":"w3:Feature Space","week":3,"kind":"concept","label":"Feature Space"},{"id":"w3:Linear Separability","week":3,"kind":"concept","label":"Linear Separability"},{"id":"w3:Feature Transformation","week":3,"kind":"concept","label":"Feature Transformation"},{"id":"w3:Polynomial Feature","week":3,"kind":"concept","label":"Polynomial Feature"},{"id":"w3:XOR","week":3,"kind":"concept","label":"XOR"},{"id":"w3:assignment:Check","week":3,"kind":"assignment","label":"Check"},{"id":"w3:assignment:Apply","week":3,"kind":"assignment","label":"Apply"},{"id":"w3:assignment:Explore","week":3,"kind":"assignment","label":"Explore"},{"id":"w4:Derivative","week":4,"kind":"concept","label":"Derivative"},{"id":"w4:Partial Derivative","week":4,"kind":"concept","label":"Partial Derivative"},{"id":"w4:Gradient","week":4,"kind":"concept","label":"Gradient"},{"id":"w4:Gradient Descent","week":4,"kind":"concept","label":"Gradient Descent"},{"id":"w4:Learning Rate","week":4,"kind":"concept","label":"Learning Rate"},{"id":"w4:Chain Rule","week":4,"kind":"concept","label":"Chain Rule"},{"id":"w4:Computational Graph","week":4,"kind":"concept","label":"Computational Graph"},{"id":"w4:assignment:Check","week":4,"kind":"assignment","label":"Check"},{"id":"w4:assignment:Apply","week":4,"kind":"assignment","label":"Apply"},{"id":"w4:assignment:Explore","week":4,"kind":"assignment","label":"Explore"},{"id":"w5:Linear Layer","week":5,"kind":"concept","label":"Linear Layer"},{"id":"w5:MLP","week":5,"kind":"concept","label":"MLP"},{"id":"w5:Activation","week":5,"kind":"concept","label":"Activation"},{"id":"w5:Sigmoid","week":5,"kind":"concept","label":"Sigmoid"},{"id":"w5:Tanh","week":5,"kind":"concept","label":"Tanh"},{"id":"w5:ReLU","week":5,"kind":"concept","label":"ReLU"},{"id":"w5:Backpropagation","week":5,"kind":"concept","label":"Backpropagation"},{"id":"w5:Autograd","week":5,"kind":"concept","label":"Autograd"},{"id":"w5:assignment:Check","week":5,"kind":"assignment","label":"Check"},{"id":"w5:assignment:Apply","week":5,"kind":"assignment","label":"Apply"},{"id":"w5:assignment:Explore","week":5,"kind":"assignment","label":"Explore"},{"id":"w6:Logit","week":6,"kind":"concept","label":"Logit"},{"id":"w6:Softmax","week":6,"kind":"concept","label":"Softmax"},{"id":"w6:Cross-Entropy","week":6,"kind":"concept","label":"Cross-Entropy"},{"id":"w6:Mini-batch","week":6,"kind":"concept","label":"Mini-batch"},{"id":"w6:Epoch","week":6,"kind":"concept","label":"Epoch"},{"id":"w6:Optimizer","week":6,"kind":"concept","label":"Optimizer"},{"id":"w6:Train/Validation/Test","week":6,"kind":"concept","label":"Train/Validation/Test"},{"id":"w6:Generalization","week":6,"kind":"concept","label":"Generalization"},{"id":"w6:Overfitting","week":6,"kind":"concept","label":"Overfitting"},{"id":"w6:assignment:Check","week":6,"kind":"assignment","label":"Check"},{"id":"w6:assignment:Apply","week":6,"kind":"assignment","label":"Apply"},{"id":"w6:assignment:Explore","week":6,"kind":"assignment","label":"Explore"},{"id":"w7:Image Tensor","week":7,"kind":"concept","label":"Image Tensor"},{"id":"w7:Convolution","week":7,"kind":"concept","label":"Convolution"},{"id":"w7:Kernel","week":7,"kind":"concept","label":"Kernel"},{"id":"w7:Feature Map","week":7,"kind":"concept","label":"Feature Map"},{"id":"w7:Stride","week":7,"kind":"concept","label":"Stride"},{"id":"w7:Padding","week":7,"kind":"concept","label":"Padding"},{"id":"w7:Channel","week":7,"kind":"concept","label":"Channel"},{"id":"w7:Pooling","week":7,"kind":"concept","label":"Pooling"},{"id":"w7:Receptive Field","week":7,"kind":"concept","label":"Receptive Field"},{"id":"w7:Inductive Bias","week":7,"kind":"concept","label":"Inductive Bias"},{"id":"w7:assignment:Check","week":7,"kind":"assignment","label":"Check"},{"id":"w7:assignment:Apply","week":7,"kind":"assignment","label":"Apply"},{"id":"w7:assignment:Explore","week":7,"kind":"assignment","label":"Explore"},{"id":"w8:Deep Network","week":8,"kind":"concept","label":"Deep Network"},{"id":"w8:Degradation","week":8,"kind":"concept","label":"Degradation"},{"id":"w8:Residual Function","week":8,"kind":"concept","label":"Residual Function"},{"id":"w8:Skip Connection","week":8,"kind":"concept","label":"Skip Connection"},{"id":"w8:Identity Mapping","week":8,"kind":"concept","label":"Identity Mapping"},{"id":"w8:Gradient Path","week":8,"kind":"concept","label":"Gradient Path"},{"id":"w8:Batch Normalization","week":8,"kind":"concept","label":"Batch Normalization"},{"id":"w8:ResNet BasicBlock","week":8,"kind":"concept","label":"ResNet BasicBlock"},{"id":"w8:assignment:Check","week":8,"kind":"assignment","label":"Check"},{"id":"w8:assignment:Apply","week":8,"kind":"assignment","label":"Apply"},{"id":"w8:assignment:Explore","week":8,"kind":"assignment","label":"Explore"}]'::jsonb) AS i(id text,week smallint,kind text,label text)
WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT(id) DO NOTHING;
-- Match concept labels, moving old weeks 2->4, 3->2, 4->3. New assignments start unchecked.
INSERT INTO learning_progress(user_id,item_id,completed,updated_at)
SELECT p.user_id,n.id,p.completed,p.updated_at
FROM curriculum_progress_archive p
JOIN curriculum_content_archive a ON a.revision=p.revision AND a.kind='items'
CROSS JOIN LATERAL jsonb_to_recordset(a.data) AS old(id text,week smallint,kind text,label text)
JOIN learning_items n ON n.kind='concept' AND n.label=old.label AND n.week=CASE old.week WHEN 2 THEN 4 WHEN 3 THEN 2 WHEN 4 THEN 3 ELSE old.week END
WHERE p.revision='revised-v2' AND p.item_id=old.id AND old.kind='concept' AND NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2')
ON CONFLICT(user_id,item_id) DO NOTHING;
-- Old custom bodies/Colab links remain in the archive. The new source becomes the default.
DELETE FROM lesson_edits WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
DELETE FROM week_quizzes WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
INSERT INTO week_quizzes(week,questions,instructions,password_hash,published,revision,updated_at)
SELECT CASE q.week WHEN 3 THEN 5 WHEN 4 THEN 3 WHEN 5 THEN 4 ELSE q.week END,
q.questions,q.instructions,q.password_hash,
CASE WHEN q.week BETWEEN 3 AND 5 THEN false ELSE q.published END,q.revision+1,now()
FROM curriculum_content_archive a
CROSS JOIN LATERAL jsonb_to_recordset(a.data) AS q(week smallint,questions jsonb,instructions text,password_hash text,published boolean,revision integer)
WHERE a.revision='revised-v2' AND a.kind='quizzes' AND NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
DELETE FROM quiz_attempts WHERE week BETWEEN 3 AND 5 AND NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
ALTER TABLE lesson_edits ADD COLUMN IF NOT EXISTS content_revision text NOT NULL DEFAULT 'revised-v2';
ALTER TABLE week_quizzes ADD COLUMN IF NOT EXISTS content_revision text NOT NULL DEFAULT 'revised-v2';
INSERT INTO curriculum_revisions(revision) VALUES('revised-v2') ON CONFLICT DO NOTHING;
